import { Order, canCancelOrder } from '../domain/Order';
import { Catalog } from '../domain/Catalog';
import { OrderRepository } from '../domain/OrderRepository';

export class CancelOrderUseCase {
  constructor(private catalog: Catalog, private orderRepository: OrderRepository) {}

  execute(orderId: string): Order {
    const order = this.orderRepository.getById(orderId);
    if (!order) {
      throw new Error(`Order ${orderId} not found`);
    }

    if (!canCancelOrder(order.state)) {
      throw new Error(`Cannot cancel order in state ${order.state}`);
    }

    // Release reserved stock
    for (const item of order.items) {
      this.catalog.release(item.productId, item.quantity);
    }

    this.orderRepository.save(order);
    return order;
  }
}

