import { Catalog } from '../domain/Catalog';

export interface StockLevel {
  productId: string;
  name: string;
  price: number;
  total: number;
  reserved: number;
  available: number;
}

export class GetStockLevelsUseCase {
  constructor(private catalog: Catalog) {}

  execute(): StockLevel[] {
    const products = this.catalog.getAllProducts();
    return products.map((product) => ({
      productId: product.id,
      name: product.name,
      price: product.price,
      total: this.catalog.getTotalStock(product.id),
      reserved: this.catalog.getReservedStock(product.id),
      available: this.catalog.getAvailableStock(product.id),
    }));
  }
}

